    ', subcampeón' => ', vice-champion',
    ', una hoja por tema:' => ', une feuille par thème :',
    ', usted gana' => ', vous gagnez',
    ', y en Datos la' => ', et dans Données le',
    ', ábrala desde el ícono y vuelva a esta página.' => ', ouvrez-la depuis l\'icône puis revenez à cette page.',
    '. Al pagar, queda como gasto en Finanzas y se imprime el comprobante para que el árbitro lo firme.' => '. Lors du paiement, il est enregistré comme dépense dans Finances et le justificatif est imprimé pour que l\'arbitre le signe.',
    '. Aplica a la escuela' => '. S\'applique à l\'école',
    '. Aplica a la liga' => '. S\'applique à la ligue',
    '. Aplica a la plataforma' => '. S\'applique à la plateforme',
    '. Cada campeonato copia estas reglas al crearse y después se pueden cambiar solo para ese campeonato (Campeonatos → el campeonato → Configuración). Su contraseña y la doble verificación están en' => '. Chaque championnat copie ces règles à sa création et elles peuvent ensuite être modifiées uniquement pour ce championnat (Championnats → le championnat → Configuration). Votre mot de passe et la double vérification se trouvent dans',
    '. Cada campeonato nuevo empieza con ellas, pero cada campeonato puede tener las suyas (se cambian en Campeonato → Configuración).' => '. Chaque nouveau championnat démarre avec celles-ci, mais chacun peut avoir les siennes (à modifier dans Championnat → Configuration).',
    '. Cada cono suma {n} s automáticamente. Toque' => '. Chaque cône ajoute automatiquement {n} s. Touchez',
    '. Con' => '. Avec',
    '. Cuando una liga se registra con su enlace o su código (o usted la asigna en Ligas → Editar), cada pago de suscripción que registre en' => '. Lorsqu\'une ligue s\'inscrit avec votre lien ou son code (ou que vous l\'attribuez dans Ligues → Modifier), chaque paiement d\'abonnement que vous enregistrez dans',
    '. Deje vacío a quien no jugó.' => '. Laissez vide pour ceux qui n\'ont pas joué.',
    '. Ejemplo, sprint de {n} m (gana el menor), {n} a {n} años: amarillo desde {n} s y verde desde {n} s.' => '. Exemple : sprint de {n} m (le plus bas gagne), {n} à {n} ans : jaune à partir de {n} s et vert à partir de {n} s.',
    '. El ganador pasa solo a la ronda siguiente.' => '. Le vainqueur passe automatiquement au tour suivant.',
    '. El interesado llena "Solicitar demo" y usted decide a quién le crea la cuenta (menú' => '. La personne intéressée remplit « Demander une démo » et vous décidez à qui créer un compte (menu',
    '. El público lo ve en la pestaña' => '. Le public le voit dans l\'onglet',
    '. En el celular:' => '. Sur mobile :',
    '. En el celular: menú ⋮ → Compartir → Imprimir → Guardar como PDF.' => '. Sur mobile : menu ⋮ → Partager → Imprimer → Enregistrer au format PDF.',
    '. Estos proveedores aplican medidas de seguridad reconocidas internacionalmente y actúan solo como proveedores de infraestructura: no usan los datos para fines propios. Al aceptar esta política, usted autoriza esta transferencia internacional, que es necesaria para que el servicio funcione.' => '. Ces prestataires appliquent des mesures de sécurité reconnues internationalement et agissent uniquement en tant que fournisseurs d\'infrastructure : ils n\'utilisent pas les données à leurs propres fins. En acceptant cette politique, vous autorisez ce transfert international, nécessaire au fonctionnement du service.',
    '. Falta que la federación lo apruebe.' => '. Il reste à la fédération à l\'approuver.',
    '. Formulario público:' => '. Formulaire public :',
    '. Funciona sin internet y sincroniza cuando vuelve la señal.' => '. Fonctionne sans internet et se synchronise dès que le signal revient.',
    '. La cédula se valida ({n} números) o se acepta pasaporte.' => '. Le numéro d\'identité est validé ({n} chiffres) ou un passeport est accepté.',
    '. La federación ve sus números, sus partidos y puede poner sanciones federativas que se aplican en sus campeonatos. Sus torneos siguen siendo solo suyos.' => '. La fédération voit vos chiffres et vos matchs, et peut prononcer des sanctions fédérales qui s\'appliquent dans vos championnats. Vos tournois restent uniquement les vôtres.',
    '. La liga la abre en cada campeonato con una fecha límite.' => '. La ligue l\'ouvre dans chaque championnat avec une date limite.',
    '. Le pediremos su cédula para comprobar que es el titular. Se responderá en el plazo que establece la ley ({n} días).' => '. Nous vous demanderons votre n° d\'identité pour vérifier que vous en êtes le titulaire. Il sera répondu dans le délai prévu par la loi ({n} jours).',
    '. Los árbitros y delegados se crean en Árbitros y en cada Equipo.' => '. Les arbitres et délégués se créent dans Arbitres et dans chaque Équipe.',
    '. Mientras más claro, más rápido lo podemos evaluar y desarrollar. Le avisamos aquí cuando tengamos novedades.' => '. Plus c\'est clair, plus vite nous pourrons l\'évaluer et le développer. Nous vous informerons ici dès que nous aurons du nouveau.',
    '. No ve los pagos de los alumnos; sí ve' => '. Il ne voit pas les paiements des élèves ; il voit',
    '. Para salir de un panel y entrar a otro, vuelva a esta página.' => '. Pour quitter un tableau de bord et entrer dans un autre, revenez à cette page.',
    '. Quien entra por su enlace queda anotado como recomendado por usted.' => '. Toute personne qui s\'inscrit via votre lien est enregistrée comme parrainée par vous.',
    '. Recibimos su solicitud de demo para' => '. Nous avons bien reçu votre demande de démo pour',
    '. Revise el correo (será su usuario) y los días de la demo.' => '. Vérifiez l\'e-mail (ce sera son identifiant) et les jours de démo.',
    '. Se rige por la Ley Orgánica de Protección de Datos Personales del Ecuador (LOPDP) y su Reglamento.' => '. Elle est régie par la Loi organique de protection des données personnelles de l\'Équateur (LOPDP) et son règlement d\'application.',
    '. Si deja vacío y pone el estado "Finalizado", se llenan solos.' => '. Si vous laissez vide et mettez le statut « Terminé », ils se remplissent automatiquement.',
    '. Si no compitió, cambie el estado (DNS, DNF o DQ). Los puestos se calculan solos.' => '. S\'il n\'a pas concouru, changez le statut (DNS, DNF ou DQ). Les places sont calculées automatiquement.',
    '. Si quiere vender las entradas de sus partidos (con QR, tarjeta o transferencia, taquilla, cortesías y parqueadero), actívela con la casilla en' => '. Si vous souhaitez vendre les billets de vos matchs (avec QR, carte ou virement, guichet, invitations et parking), activez-la avec la case à cocher dans',
    '. Si su escuela es recreativa, déjelo apagado: el menú queda más simple.' => '. Si votre école est récréative, laissez cette option désactivée : le menu est plus simple.',
    '. También se puede subir después.' => '. Vous pouvez aussi le téléverser plus tard.',
    '. Tarea automática: última vez' => '. Tâche automatique : dernière exécution',
    '. Toque' => '. Touchez',
    '. Usted aprueba o rechaza con una respuesta; todo queda registrado y sale en el boletín de la fecha.' => '. Vous approuvez ou refusez par une réponse ; tout est enregistré et figure dans le bulletin de la journée.',
