    'Al cargar los tiempos, en cada etapa se marca cuántas veces se aplicó cada una y el sistema suma (o resta) los segundos. Use un valor negativo para una bonificación (ej: meta volante −{n}). Si cambia un valor, las clasificaciones se recalculan.' => 'Lors de la saisie des temps, pour chaque étape on indique combien de fois chacune a été appliquée et le système ajoute (ou retranche) les secondes. Utilisez une valeur négative pour une bonification (ex. : sprint intermédiaire −{n}). Si vous modifiez une valeur, les classements sont recalculés.',
    'Al cargar los tiempos, en cada manga se marca cuántas veces se aplicó cada una y el sistema suma (o resta) los segundos. Use un valor negativo para una bonificación (ej: meta volante −{n}). Si cambia un valor, las clasificaciones se recalculan.' => 'Lors de la saisie des temps, pour chaque manche on indique combien de fois chacune a été appliquée et le système ajoute (ou retranche) les secondes. Utilisez une valeur négative pour une bonification (ex. : sprint intermédiaire −{n}). Si vous modifiez une valeur, les classements sont recalculés.',
    'Al crear la cuenta desde una solicitud. Puede cambiarlo en cada una.' => 'À la création du compte depuis une demande. Modifiable pour chacune.',
    'Al día' => 'À jour',
    'Al día ✓' => 'À jour ✓',
    'Al elegir el alumno se sugiere su categoría con su último peso medido.' => 'En choisissant l\'élève, sa catégorie est suggérée d\'après son dernier poids mesuré.',
    'Al guardar, el sistema le avisa si hay un árbitro, una cancha o un equipo con dos partidos a la vez.' => 'À l\'enregistrement, le système vous avertit si un arbitre, un terrain ou une équipe a deux matchs en même temps.',
    'Al terminar la fase regular, el sistema arma la llave con los mejores de la tabla (tabla única): el {n}º contra el último clasificado, y los de un mismo grupo no se cruzan en la primera ronda.' => 'À la fin de la phase régulière, le système construit le tableau avec les meilleurs du classement (classement unique) : le {n}e contre le dernier qualifié, et les équipes d\'un même groupe ne se croisent pas au premier tour.',
    'Al terminar la fase regular, el sistema arma la llave con los mejores de la tabla ({n} grupos): el {n}º contra el último clasificado, y los de un mismo grupo no se cruzan en la primera ronda.' => 'À la fin de la phase régulière, le système construit le tableau avec les meilleurs du classement ({n} groupes) : le {n}er contre le dernier qualifié, et ceux d\'un même groupe ne se rencontrent pas au premier tour.',
