    'Con el' => 'Avec le',
    'Con el combo liga + escuela maneja las dos con el mismo usuario y paga {n}% menos en cada plan.' => 'Avec le pack ligue + école, vous gérez les deux avec le même identifiant et payez {n} % de moins sur chaque forfait.',
    'Con el plan' => 'Avec le forfait',
    'Con el plan Profesional imprime el fixture completo de cada campeonato (con o sin resultados) y ve el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces, que se llenan solos con los clasificados.' => 'Avec le forfait Professionnel, vous imprimez le calendrier complet de chaque championnat (avec ou sans résultats) et voyez le schéma de tout le tournoi dès le premier jour : groupes, journées et le tableau de la phase finale avec les affiches, qui se remplissent automatiquement avec les qualifiés.',
    'Con este enlace, cualquiera agrega todos los partidos del campeonato al calendario de su celular (y se actualiza solo). Cada equipo tiene el suyo en su página pública.' => 'Avec ce lien, n\'importe qui ajoute tous les matchs du championnat au calendrier de son téléphone (et il se met à jour automatiquement). Chaque équipe a le sien sur sa page publique.',
    'Con la misma cédula se agrupan hermanos (descuento).' => 'Les frères et sœurs sont regroupés par la même pièce d\'identité (remise).',
    'Con las marcadas:' => 'Avec la sélection :',
    'Con menos, el equipo pierde por W.O.' => 'Avec moins, l\'équipe perd par forfait.',
    'Con parqueadero' => 'Avec parking',
    'Con su correo y contraseña, el delegado entra a' => 'Avec son e-mail et son mot de passe, le délégué accède à',
