    'Con un plan pagado puede subir de una sola vez todos sus' => 'Avec un forfait payant, vous pouvez importer en une seule fois tous vos',
    'Con un plan pagado puede subir de una sola vez todos sus equipos, jugadores, árbitros, canchas y competidores desde Excel, y descargar una copia de todos sus datos cuando quiera.' => 'Avec un forfait payant, vous pouvez importer en une seule fois toutes vos équipes, joueurs, arbitres, terrains et concurrents depuis Excel, et télécharger une copie de toutes vos données quand vous le souhaitez.',
    'Con y sin factura' => 'Avec et sans facture',
