    'Cuando la organización ingresa en el sistema los datos de otra persona (por ejemplo, al inscribir a un jugador o importar una lista), declara contar con la autorización de esa persona o de su representante, y esa declaración también queda registrada.' => 'Lorsque l\'organisation saisit dans le système les données d\'une autre personne (par exemple en inscrivant un joueur ou en important une liste), elle déclare disposer de l\'autorisation de cette personne ou de son représentant légal, et cette déclaration est également enregistrée.',
    'Cuando las clases tengan ejercicios, aquí verá cuánto tiempo fue técnico, táctico, físico o juego.' => 'Lorsque les cours comportent des exercices, vous verrez ici combien de temps a été consacré au technique, au tactique, au physique ou au jeu.',
    'Cuando se juega cada partido, el ganador pasa solo a la siguiente ronda (en empate, cuentan los penales). Si corrige un resultado, el clasificado se corrige también.' => 'À chaque match joué, le vainqueur passe automatiquement au tour suivant (en cas d\'égalité, les tirs au but comptent). Si vous corrigez un résultat, le qualifié est corrigé aussi.',
    'Cuando un alumno está en otro grupo (otro deporte), esa mensualidad lleva este descuento.' => 'Lorsqu\'un élève est dans un autre groupe (autre sport), cette mensualité bénéficie de cette remise.',
    'Cuartos de final' => 'Quarts de finale',
    'Cuartos, semifinal y final se arman solos con la tabla, y el ganador avanza solo.' => 'Les quarts, la demi-finale et la finale se construisent automatiquement à partir du classement, et le vainqueur avance automatiquement.',
