    'Ej: {n}' => 'Ex : {n}',
    'Ej: {n} = al llegar a {n} amarillas se suspende. En básquet cuentan las faltas técnicas.' => 'Ex : {n} = à {n} jaunes, suspension. Au basket, les fautes techniques comptent.',
    'Ej: {n} = en Sub-{n} se permite un pasado de hasta {n} años. {n} = sin límite.' => 'Ex : {n} = en U-{n}, un joueur hors-âge de {n} ans maximum est autorisé. {n} = sans limite.',
    'Ej: {n} = gana del primer año de cada liga. {n} = mientras la liga siga pagando.' => 'Ex : {n} = gagne à partir de la première année de chaque ligue. {n} = tant que la ligue continue de payer.',
    'Ej: {n} = partido al mejor de {n} sets.' => 'Ex : {n} = match au meilleur des {n} sets.',
    'Ej: {n} = vence el {n} de cada mes.' => 'Ex : {n} = échéance le {n} de chaque mois.',
    'Ej: {n} a {n} cc' => 'Ex : {n} à {n} cm³',
    'Ej: {n} equipos' => 'Ex : {n} équipes',
    'Ej: {n} equipos · {n} alumnos' => 'Ex : {n} équipes · {n} élèves',
    'Ej: {n} kg' => 'Ex : {n} kg',
    'Ej: {n} m libre' => 'Ex : {n} m nage libre',
    'Ej: {n} m planos' => 'Ex : {n} m plat',
    'Ej: {n} o {n}.' => 'Ex : {n} ou {n}.',
    'Ej: {n} si hizo {n} goles.' => 'Ex : {n} s\'il a marqué {n} buts.',
    'Ej: {n} y {n} años' => 'Ex : {n} et {n} ans',
    'Ej: {n}-{n}, {n}-{n}, {n}-{n}' => 'Ex. : {n}-{n}, {n}-{n}, {n}-{n}',
    'Ej: {n}-{n}-{n}' => 'Ex : {n}-{n}-{n}',
    'Ej: {n}. {n} = sin límite. La vocalía avisa cuando un jugador llega.' => 'Ex : {n}. {n} = sans limite. La feuille de match signale quand un joueur atteint ce seuil.',
    'Ej: {n}/{n}/{n}. Sirve para la categoría Sub.' => 'Ex. : {n}/{n}/{n}. Sert pour la catégorie U.',
    'Ej: {n}er quimestre {n}' => 'Ex : {n}er quimestre {n}',
    'Ej: «en Finanzas» o «en la página pública de la liga».' => 'Ex. : « dans Finances » ou « sur la page publique de la ligue ».',
    'Ej: «en un Excel» o «a mano en un cuaderno».' => 'Ex. : « dans un Excel » ou « à la main dans un cahier ».',
    'Ej: «hoy los delegados me mandan las fotos por WhatsApp y se me pierden».' => 'Ex. : « aujourd\'hui les délégués m\'envoient les photos par WhatsApp et je les perds ».',
    'Ej: ¿Quién fue el mejor jugador de la final?' => 'Ex : Qui a été le meilleur joueur de la finale ?',
    'Ejemplo' => 'Exemple',
    'Ejemplo, sprint de 30 m (gana el menor), 10 a 11 años: amarillo desde 5,9 s y verde desde 5,4 s → 5,3 s es verde, 5,7 s es amarillo y 6,1 s es rojo.' => 'Exemple : sprint de 30 m (le plus bas gagne), 10 à 11 ans : jaune à partir de 5,9 s et vert à partir de 5,4 s → 5,3 s est vert, 5,7 s est jaune et 6,1 s est rouge.',
    'Ejemplo:' => 'Exemple :',
    'Ejemplo: Escuela Completo (${n}) + Profesional (${n}) =' => 'Exemple : École Complet (${n}) + Professionnel (${n}) =',
    'Ejemplo: Profesional (${n}) + Escuela Completo (${n}) =' => 'Exemple : Professionnel (${n}) + École Complet (${n}) =',
    'Ejercer mis derechos' => 'Exercer mes droits',
    'Ejercer mis derechos · Academia Prueba' => 'Exercer mes droits · Academia Prueba',
    'Ejercer mis derechos · Escuela Demo TuAcademia' => 'Exercer mes droits · Escuela Demo TuAcademia',
    'Ejercer mis derechos · Escuela Goleadores' => 'Exercer mes droits · École Goleadores',
    'Ejercer mis derechos · Federación Deportiva Demo' => 'Exercer mes droits · Federación Deportiva Demo',
    'Ejercer mis derechos · Liga Barrial Norte' => 'Exercer mes droits · Liga Barrial Norte',
    'Ejercer mis derechos · Liga Demo TuAcademia' => 'Exercer mes droits · Liga Demo TuAcademia',
    'Ejercer mis derechos · Liga Referida Test' => 'Exercer mes droits · Liga Referida Test',
    'Ejercicio de la biblioteca' => 'Exercice de la bibliothèque',
    'Ejercicios' => 'Exercices',
    'Ejercicios de la clase' => 'Exercices du cours',
    'El' => 'Le',
    'El archivo está vacío: debe tener la fila de títulos y al menos una fila con datos.' => 'Le fichier est vide : il doit contenir la ligne de titres et au moins une ligne de données.',
    'El archivo tiene más de' => 'Le fichier contient plus de',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el objetivo es pasar la línea media con control.' => 'Le gardien commence avec les défenseurs contre {n} ou {n} attaquants qui pressent ; l\'objectif est de passer la ligne médiane en contrôle.',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el …' => 'Le gardien relance avec les défenseurs contre {n} ou {n} attaquants qui pressent ; le …',
    'El asistente' => 'L\'assistant',
    'El asistente nunca puede crear ni cambiar usuarios. Puede cambiar estos permisos cuando quiera; valen desde la siguiente página que abra.' => 'L\'assistant ne peut jamais créer ni modifier d\'utilisateurs. Vous pouvez changer ces autorisations quand vous voulez ; elles s\'appliquent dès la page suivante qu\'il ouvre.',
    'El cliente le escribe aquí para confirmar o pagar.' => 'Le client vous écrit ici pour confirmer ou payer.',
    'El cobro con tarjeta se está terminando de conectar con Plux. Ya puede dejarlo configurado; el botón de pago aparecerá cuando esté listo.' => 'Le paiement par carte est en cours de finalisation avec Plux. Vous pouvez déjà le configurer ; le bouton de paiement apparaîtra quand il sera prêt.',
    'El código' => 'Le code',
    'El delegado sube la foto de su transferencia y el recibo sale al aprobarla.' => 'Le délégué téléverse la photo de son virement et le reçu est émis dès l\'approbation.',
    'El enlace' => 'Le lien',
    'El entrenador pasa desde afuera del área; el jugador controla orientado hacia el arco y remata en máximo 2 toques.' => 'L\'entraîneur passe depuis l\'extérieur de la surface ; le joueur contrôle orienté vers le but et frappe en 2 touches maximum.',
    'El equipo' => 'L\'équipe',
    'El examen está cerrado. Ábralo de nuevo para corregir resultados.' => 'L\'examen est clôturé. Rouvrez-le pour corriger les résultats.',
    'El examen está cerrado. Ábralo de nuevo para inscribir.' => 'L\'examen est clôturé. Rouvrez-le pour inscrire des élèves.',
    'El fixture completo de cada campeonato en PDF (con resultados o en blanco para llenar a mano) y el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces (1° Grupo A vs 2° Grupo B), que se llenan solos con los clasificados.' => 'Le calendrier complet de chaque championnat en PDF (avec résultats ou vierge à remplir à la main) et le schéma de tout le tournoi dès le premier jour : groupes, journées et le tableau de la phase finale avec les affiches (1er Groupe A vs 2e Groupe B), qui se remplissent automatiquement avec les qualifiés.',
    'El ganador de cada partido pasa solo a la siguiente ronda.' => 'Le vainqueur de chaque match passe automatiquement au tour suivant.',
    'El idioma con el que se abre su página para el público. Cada visitante (y cada usuario del panel) puede cambiarlo con el botón 🌐 de arriba.' => 'La langue dans laquelle s\'ouvre votre page publique. Chaque visiteur (et chaque utilisateur du tableau de bord) peut la changer avec le bouton 🌐 en haut.',
    'El informe de desarrollo reúne la asistencia, los gráficos de tests (comparados con su categoría), la evaluación técnica, las insignias, las metas y el comentario del profesor del trimestre. La familia también lo ve en su portal y lo puede guardar en PDF.' => 'Le rapport de développement réunit la présence, les graphiques des tests (comparés à sa catégorie), l\'évaluation technique, les badges, les objectifs et le commentaire de l\'entraîneur pour le trimestre. La famille le voit aussi dans son portail et peut l\'enregistrer en PDF.',
    'El informe del árbitro' => 'Le rapport de l\'arbitre',
    'El jugador autorizó' => 'Le joueur a autorisé',
    'El jugador no insultó al árbitro; pedimos revisar el video.' => 'Le joueur n\'a pas insulté l\'arbitre ; nous demandons de revoir la vidéo.',
    'El lector' => 'Le lecteur',
    'El pago con tarjeta no se completó.' => 'Le paiement par carte n\'a pas abouti.',
    'El perfil' => 'Le profil',
    'El precio incluye' => 'Le prix comprend',
    'El profesor dio la clase' => 'L\'entraîneur a donné le cours',
    'El profesor planifica las clases por adelantado con la biblioteca de ejercicios de la escuela; cada clase guarda ejercicios, minutos, intensidad, fotos y una nota para cada alumno, y los padres ven el diario de entrenamientos de su hijo.' => 'L\'entraîneur planifie les cours à l\'avance avec la bibliothèque d\'exercices de l\'école ; chaque cours enregistre exercices, minutes, intensité, photos et une note pour chaque élève, et les parents consultent le journal d\'entraînement de leur enfant.',
    'El profesor toma lista en segundos y anota el plan de la clase.' => 'L\'entraîneur fait l\'appel en quelques secondes et note le plan du cours.',
    'El público reserva sus canchas por horas desde el celular y el cobro entra a finanzas.' => 'Le public réserve ses terrains à l\'heure depuis son téléphone et l\'encaissement est enregistré dans les finances.',
    'El público vota desde la página de la liga (pestaña' => 'Le public vote depuis la page de la ligue (onglet',
    'El que corresponda por su edad' => 'Celui qui correspond à son âge',
    'El que está en curso' => 'Celui qui est en cours',
    'El representante ve en su celular la asistencia, los pagos, las evaluaciones, la libreta y el carnet de sus hijos, y puede subir el comprobante de pago.' => 'Le représentant voit sur son téléphone la présence, les paiements, les évaluations, le carnet scolaire et la carte de ses enfants, et peut envoyer le justificatif de paiement.',
    'El semáforo de cada resultado sale solo:' => 'Le code couleur de chaque résultat s\'affiche automatiquement :',
    'El sistema completo para administrar tu liga de fútbol' => 'Le système complet pour gérer votre ligue de football',
    'El sistema completo para su escuela deportiva' => 'Le système complet pour votre école de sport',
    'El sistema le avisa por Telegram cuando alguien pide una demo, cuando a una demo le quedan {n} días (día {n}) y el día que vence (día {n}), con el mensaje de WhatsApp listo para enviar.' => 'Le système vous avertit par Telegram lorsque quelqu\'un demande une démo, lorsqu\'il reste {n} jours à une démo (jour {n}) et le jour de son échéance (jour {n}), avec le message WhatsApp prêt à envoyer.',
    'El sistema pone a cada alumno en su categoría por edad (Sub-{n}, Sub-{n}, Sub-{n}…) o en grupos abiertos.' => 'Le système place chaque élève dans sa catégorie d\'âge (U-{n}, U-{n}, U-{n}…) ou dans des groupes ouverts.',
    'El sistema reparte horarios, canchas y árbitros sin choques, o lo hace usted a mano.' => 'Le système répartit horaires, terrains et arbitres sans conflit, ou vous le faites manuellement.',
    'El sistema reparte los equipos al azar y puede generar el fixture de una vez.' => 'Le système répartit les équipes au hasard et peut générer le calendrier en une seule fois.',
    'El sistema reparte los partidos en las canchas y horarios que usted indique, sin que un equipo o un árbitro tenga dos partidos a la vez, alternando a los equipos entre horarios temprano y tarde y repartiendo los partidos entre los árbitros. Primero ve la propuesta y luego decide si la guarda.' => 'Le système répartit les matchs sur les terrains et les horaires que vous indiquez, sans qu\'une équipe ou un arbitre ait deux matchs en même temps, en alternant les équipes entre horaires matinaux et tardifs et en répartissant les matchs entre les arbitres. Vous voyez d\'abord la proposition, puis vous décidez de l\'enregistrer ou non.',
    'El sistema suma lo que se le debe a cada árbitro por los partidos jugados, según su función (central, asistente, cuarto). El valor por partido se pone en cada campeonato:' => 'Le système additionne ce qui est dû à chaque arbitre pour les matchs joués, selon sa fonction (central, assistant, quatrième). Le montant par match se définit dans chaque championnat :',
    'El sistema ya está en inglés, francés, portugués e italiano: use el botón 🌐 de la barra de arriba. Elija el idioma de su página pública en Parámetros.' => 'Le système est désormais disponible en anglais, français, portugais et italien : utilisez le bouton 🌐 de la barre du haut. Choisissez la langue de votre page publique dans Paramètres.',
    'El video pesa más de' => 'La vidéo pèse plus de',
    'El vocal abre este enlace en su' => 'L\'officiel de table ouvre ce lien sur son',
    'El vocal escanea el carnet y ve la foto:' => 'L\'officiel de table scanne la carte et voit la photo :',
    'El vocal escanea el carnet y ve la foto: se acabaron las suplantaciones.' => 'L\'officiel de table scanne la carte et voit la photo : fini les usurpations d\'identité.',
    'El vocal escanea este QR en la cancha. La hora en vivo demuestra que no es una captura de pantalla.' => 'L\'officiel de table scanne ce QR sur le terrain. L\'heure en direct prouve que ce n\'est pas une capture d\'écran.',
    'El vocal marca desde el celular y los hinchas ven el marcador al instante en la página de la liga.' => 'L\'officiel de table saisit depuis son téléphone et les supporters voient le score instantanément sur la page de la ligue.',
    'El vocal registra goles, tarjetas, cambios y reloj desde el celular (funciona aunque se caiga el internet). El público ve el marcador en vivo, se escanea el carnet QR y sale la hoja de vocalía en PDF.' => 'L\'officiel de table enregistre buts, cartons, remplacements et chronomètre depuis son téléphone (fonctionne même sans internet). Le public voit le score en direct, la carte QR se scanne et la feuille de match sort en PDF.',
    'El árbitro' => 'L\'arbitre',
    'El árbitro todavía no ha llenado el informe.' => 'L\'arbitre n\'a pas encore rempli le rapport.',
    'El último set (ej:' => 'Le dernier set (ex :',
    'El último set (ej: el {n}º) puede ser más corto.' => 'Le dernier set (ex : le {n}e) peut être plus court.',
    'Elegir cuáles incluir →' => 'Choisir lesquels inclure →',
    'Elija' => 'Choisissez',
    'Elija Taekwondo, Karate o Judo como deporte del grupo y tendrá: su propia lista de cinturones (kup/dan con puntas), categorías de peso oficiales, poomsae o kata de cada cinturón y exámenes de grado con cobro, acta y certificado con código QR. Está en Alumnos → Exámenes de grado.' => 'Choisissez Taekwondo, Karaté ou Judo comme sport du groupe et vous aurez : votre propre liste de ceintures (kup/dan avec pointes), les catégories de poids officielles, le poomsae ou kata de chaque ceinture et des passages de grade avec facturation, procès-verbal et certificat avec code QR. C\'est dans Élèves → Passages de grade.',
    'Elija el' => 'Choisissez le',
    'Elija la' => 'Choisissez la',
    'Elija la disciplina del examen.' => 'Choisissez la discipline de l\'examen.',
