    'Elija la otra cuenta del mismo dueño (una liga para una escuela nueva, o una escuela para una liga nueva). Si deja vacíos los datos del administrador, el dueño entra con su' => 'Choisissez l\'autre compte du même propriétaire (une ligue pour une nouvelle école, ou une école pour une nouvelle ligue). Si vous laissez vides les données de l\'administrateur, le propriétaire se connecte avec son',
    'Elija primero una liga o escuela.' => 'Choisissez d\'abord une ligue ou une école.',
