    'En el trimestre vino a' => 'Au cours du trimestre, il est venu à',
    'En formativas todos deben jugar. La línea es el promedio del grupo: los que están muy abajo necesitan más minutos.' => 'En catégories de formation, tous doivent jouer. La ligne est la moyenne du groupe : ceux qui sont bien en dessous ont besoin de plus de minutes.',
    'En fútbol incluye al arquero. Ecuavóley:' => 'Au football, inclut le gardien. Ecuavóley :',
    'En fútbol incluye al arquero. Ecuavóley: {n}. Básquet: {n} (o {n}).' => 'Au football, inclut le gardien. Ecuavóley : {n}. Basket : {n} (ou {n}).',
    'En juego' => 'En cours',
    'En la' => 'Dans la',
    'En la demostración no se abren tickets.' => 'Dans la démo, les tickets ne sont pas ouverts.',
    'En la demostración no se generan enlaces de recomendación. Cuando tenga su cuenta, aquí estará su enlace.' => 'Dans la démo, aucun lien de parrainage n\'est généré. Une fois votre compte créé, votre lien sera ici.',
    'En la demostración no se suben videos. Mire el ejemplo en el portal del jugador o de los padres.' => 'Dans la démo, il n\'est pas possible de téléverser des vidéos. Consultez l\'exemple dans le portail du joueur ou des parents.',
    'En la demostración no se suben videos. Vea cómo le llega al padre de familia:' => 'Aucune vidéo n\'est téléversée dans la démo. Voyez comment le parent la reçoit :',
    'En los portales de jugador y de familia, si le piden clave, es' => 'Sur les portails joueur et famille, si un code vous est demandé, c\'est',
    'En los últimos 4 meses.' => 'Au cours des 4 derniers mois.',
