    'Enlace para el vocal' => 'Lien pour l\'officiel de table',
    'Entra a su panel y ve solo sus pagos:' => 'Il accède à son tableau de bord et ne voit que ses paiements :',
    'Entra a su panel y ve solo sus pagos: quién pagó, cuánto, la comisión y lo que le transferimos.' => 'Il accède à son tableau de bord et ne voit que ses paiements : qui a payé, combien, la commission et ce que nous lui avons versé.',
    'Entrada' => 'Billet',
