    'Entrar al panel' => 'Accéder au tableau de bord',
    'Entre a' => 'Allez sur',
    'Entre a la página de cada escuela:' => 'Accédez à la page de chaque école :',
    'Entre a la página de cada escuela: grupos, horarios e inscripción en línea.' => 'Accédez à la page de chaque école : groupes, horaires et inscription en ligne.',
    'Entre a la página de cada liga:' => 'Accédez à la page de chaque ligue :',
    'Entre a la página de cada liga: resultados en vivo, tabla, fixture y goleadores.' => 'Accédez à la page de chaque ligue : résultats en direct, classement, calendrier et buteurs.',
    'Entre con un clic a cada panel, como si fuera el administrador, el árbitro, el delegado, el vocal o el jugador. Puede probar y guardar lo que quiera: los datos vuelven a estar como nuevos cada madrugada.' => 'Accédez en un clic à chaque tableau de bord, comme si vous étiez l\'administrateur, l\'arbitre, le délégué, l\'officiel de table ou le joueur. Vous pouvez tester et enregistrer ce que vous voulez : les données sont réinitialisées chaque nuit.',
