    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el forma de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Voici la liste utilisée par votre école, dans l\'ordre du premier au dernier. Vous pouvez modifier le grade, le nom, les couleurs, la pointe et la forme de chaque ceinture, ou décocher celles que vous n\'utilisez pas. L\'ordre détermine la « ceinture suivante » de chaque élève.',
    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el kata de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Voici la liste utilisée par votre école, dans l\'ordre du premier au dernier. Vous pouvez modifier le grade, le nom, les couleurs, la pointe et le kata de chaque ceinture, ou décocher celles que vous n\'utilisez pas. L\'ordre détermine la « ceinture suivante » de chaque élève.',
    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el poomsae de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Voici la liste utilisée par votre école, dans l\'ordre du premier au dernier. Vous pouvez modifier le grade, le nom, les couleurs, la pointe et le poomsae de chaque ceinture, ou décocher celles que vous n\'utilisez pas. L\'ordre détermine la « ceinture suivante » de chaque élève.',
