    'La inscripción en línea está' => 'L\'inscription en ligne est',
    'La liga de demostración no se cuenta. "Ingreso mensual estimado" = último pago de cada liga pagando dividido para los meses que cubre.' => 'La ligue de démonstration n\'est pas comptée. « Revenu mensuel estimé » = dernier paiement de chaque ligue payante divisé par le nombre de mois qu\'il couvre.',
    'La maduración se calcula con la fórmula de Mirwald (talla, talla sentado, peso, edad y género). Dos chicos de la misma edad pueden estar hasta {n} años distintos en su desarrollo: esto ayuda a no descartar a los que maduran tarde y a cuidar la carga de los que están en pleno estirón.' => 'La maturation est calculée avec la formule de Mirwald (taille, taille assis, poids, âge et sexe). Deux jeunes du même âge peuvent différer de jusqu\'à {n} ans dans leur développement : cela aide à ne pas écarter ceux qui mûrissent tard et à surveiller la charge de ceux qui sont en pleine poussée de croissance.',
    'La organización (declara tenerla)' => 'L\'organisation (déclare l\'avoir)',
    'La persona' => 'La personne',
    'La persona (por su cédula) queda' => 'La personne (par son n° d\'identité) est',
    'La pestaña' => 'L\'onglet',
    'La plantilla trae las columnas de ese deporte (pareja, peso, grado, vehículo, pruebas…) y en la hoja «Instrucciones» la lista de categorías o pruebas del campeonato.' => 'Le modèle contient les colonnes de ce sport (partenaire, poids, grade, véhicule, épreuves…) et, dans la feuille « Instructions », la liste des catégories ou épreuves du championnat.',
    'La prueba gratis automática está' => 'L\'essai gratuit automatique est',
    'La página de la liga se actualiza sola:' => 'La page de la ligue se met à jour automatiquement :',
    'La página de la liga se actualiza sola: marcador, minuto y goleadores al instante.' => 'La page de la ligue se met à jour automatiquement : score, minute et buteurs instantanément.',
    'La página de la liga y su Resumen muestran los jugadores que cumplen años hoy (con su edad) y los equipos que se acercan a su aniversario (ponga la' => 'La page de la ligue et son Aperçu affichent les joueurs dont c\'est l\'anniversaire aujourd\'hui (avec leur âge) et les équipes dont l\'anniversaire approche (indiquez la',
    'La página de su escuela con su propia dirección (www.suescuela.com) en vez de tuacademia.tukanec.com/su-escuela.' => 'La page de votre école avec sa propre adresse (www.suescuela.com) au lieu de tuacademia.tukanec.com/su-escuela.',
    'La página de verificación del carnet (a la que se llega escaneando el QR) muestra la foto y la cédula parcialmente oculta, solo para identificar al participante.' => 'La page de vérification de la carte (accessible en scannant le QR) affiche la photo et le n° d\'identité partiellement masqué, uniquement pour identifier le participant.',
    'La tabla aparece cuando se juegue el primer partido pronosticado.' => 'Le classement apparaît dès que le premier match pronostiqué est joué.',
    'La ven los padres' => 'Visible par les parents',
    'La venta de entradas de este partido ya está cerrada.' => 'La vente de billets pour ce match est désormais fermée.',
    'La venta de entradas está' => 'La vente de billets est',
    'La vocalía no deja marcar más presentes.' => 'La feuille de match ne permet pas de marquer plus de présents.',
    'La vocalía sigue funcionando:' => 'La feuille de match continue de fonctionner :',
    'La vocalía sigue funcionando: guarda los goles, tarjetas y presentes en el celular y los envía solos cuando vuelve la señal.' => 'La feuille de match continue de fonctionner : elle enregistre les buts, cartons et présents sur le téléphone et les envoie automatiquement dès que le signal revient.',
    'Lanzamiento de bala' => 'Lancer du poids',
    'Lanzamiento de bala · Damas {n} y {n} años' => 'Lancer du poids · Dames {n} et {n} ans',
    'Lanzamiento de bala · Varones {n} y {n} años' => 'Lancer du poids · Hommes {n} et {n} ans',
    'Lanzamiento de disco' => 'Lancer du disque',
    'Lanzamiento de jabalina' => 'Lancer du javelot',
    'Las canchas se administran en' => 'Les terrains se gèrent dans',
    'Las demás medidas (cadera, brazo, muslo, % grasa, envergadura) se registran en la ficha de cada alumno.' => 'Les autres mesures (hanches, bras, cuisse, % de masse grasse, envergure) sont enregistrées dans la fiche de chaque élève.',
    'Las facturas electrónicas' => 'Les factures électroniques',
    'Las familias suben aquí la foto de su transferencia desde su portal. Revise que el dinero llegó y apruébelo: se emite el recibo.' => 'Les familles envoient ici la photo de leur virement depuis leur portail. Vérifiez que l\'argent est bien arrivé et approuvez-le : le reçu est émis.',
    'Las fotos no van en el Excel: se suben después en cada equipo, o las sube cada delegado.' => 'Les photos ne vont pas dans le fichier Excel : elles sont téléversées ensuite dans chaque équipe, ou par chaque délégué.',
    'Las fotos no van en el Excel: se suben después en la ficha de cada persona. Máximo' => 'Les photos ne vont pas dans le fichier Excel : elles sont téléversées ensuite dans la fiche de chaque personne. Maximum',
    'Las fotos no van en el Excel: se suben después en la ficha de cada persona. Máximo {n} filas por archivo. También acepta archivos CSV.' => 'Les photos ne vont pas dans l\'Excel : elles se téléversent ensuite dans la fiche de chaque personne. Maximum {n} lignes par fichier. Les fichiers CSV sont aussi acceptés.',
    'Las fotos y los comprobantes no van en el Excel. Para subir datos desde Excel use' => 'Les photos et les reçus ne vont pas dans le fichier Excel. Pour importer des données depuis Excel, utilisez',
    'Las ligas y escuelas le pagan su suscripción con tarjeta, y sus equipos y familias les pagan a ellas con TuAcademia de intermediario. Reporte y transferencias en' => 'Les ligues et écoles vous paient leur abonnement par carte, et leurs équipes et familles les paient via TuAcademia comme intermédiaire. Rapport et virements dans',
    'Las medidas se toman en' => 'Les mesures sont prises dans',
    'Las mensualidades se generan solas' => 'Les mensualités sont générées automatiquement',
    'Las mensualidades se generan solas, con su fecha de vencimiento, becas y descuento por hermanos.' => 'Les mensualités sont générées automatiquement, avec leur date d\'échéance, bourses et remise fratrie.',
    'Las opciones son los goles de esa jornada (en básquet, los triples).' => 'Les options sont les buts de cette journée (au basket, les trois points).',
    'Las opciones son los jugadores presentes (si la vocalía los marcó) o las dos plantillas.' => 'Les options sont les joueurs présents (si la feuille de match les a marqués) ou les deux effectifs.',
    'Las reglas vienen llenas con los valores por defecto de la liga. Cámbielas solo si este campeonato es distinto (otra modalidad, otra duración, otro número de árbitros, etc.).' => 'Les règles sont préremplies avec les valeurs par défaut de la ligue. Modifiez-les uniquement si ce championnat est différent (autre modalité, autre durée, autre nombre d\'arbitres, etc.).',
    'Le ayudamos a cargar sus alumnos y grupos' => 'Nous vous aidons à importer vos élèves et vos groupes',
    'Le ayudamos a cargar sus equipos y su primer campeonato' => 'Nous vous aidons à importer vos équipes et votre premier championnat',
    'Le faltan' => 'Il manque',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo (Liga Demo TuAcademia). Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires d\'Atlético Chimborazo (Liga Demo TuAcademia). Gratuit, sans Telegram ni WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Atlético Chimborazo. Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires d\'Atlético Chimborazo. Gratuit, sans Telegram ni WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Deportivo Los Andes (Liga Demo TuAcademia). Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires de Deportivo Los Andes (Liga Demo TuAcademia). Gratuit, sans Telegram ni WhatsApp.',
