    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Estrella del Sur. Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires d\'Estrella del Sur. Gratuit, sans Telegram ni WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Leones. Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires de Leones. Gratuit, sans Telegram ni WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Pumas. Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires de Pumas. Gratuit, sans Telegram ni WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Real Cotopaxi. Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires de Real Cotopaxi. Gratuit, sans Telegram ni WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Tigres. Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires de Tigres. Gratuit, sans Telegram ni WhatsApp.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de {s}.' => 'Vous recevez une notification sur votre téléphone à chaque but, avec le score final et les horaires de {s}.',
    'Le llega un aviso al celular con cada gol, el resultado final y los horarios de Águilas FC. Gratis, sin Telegram ni WhatsApp.' => 'Vous recevez une notification sur votre téléphone pour chaque but, le résultat final et les horaires d\'Águilas FC. Gratuit, sans Telegram ni WhatsApp.',
    'Le llegan avisos de sus goles, resultados y horarios. Para seguir otro equipo, ábralo en la página de su liga y toque' => 'Vous recevez des notifications de vos buts, résultats et horaires. Pour suivre une autre équipe, ouvrez-la sur la page de sa ligue et appuyez sur',
    'Le mostramos el sistema con un asesor y le creamos su acceso de prueba para su escuela, con sus propios datos.' => 'Nous vous présentons le système avec un conseiller et créons votre accès de test pour votre école, avec vos propres données.',
    'Le mostramos el sistema con un asesor y le creamos su acceso de prueba para su liga, con sus propios datos.' => 'Nous vous présentons le système avec un conseiller et créons votre accès de test pour votre ligue, avec vos propres données.',
