    'Llene este formulario y la liga queda funcionando con su administrador, su página pública y (si quiere) su primer campeonato. No hay que copiar archivos ni tocar el servidor.' => 'Remplissez ce formulaire et la ligue est opérationnelle avec son administrateur, sa page publique et (si vous le souhaitez) son premier championnat. Pas besoin de copier des fichiers ni de toucher au serveur.',
    'Lo asume la liga (el que paga ve el valor exacto; a usted le llega el valor menos la comisión)' => 'Prise en charge par la ligue (le payeur voit le montant exact ; vous recevez le montant moins la commission)',
    'Lo básico (Equipos y jugadores con foto, Sorteo y fixture automático (todos contra todos, grupos, ida y vuelta), Llaves eliminatorias automáticas, Tabla de posiciones, goleadores y tarjetas, Suspensiones automáticas y sanciones…) viene en todos los planes. Marque los módulos que trae este plan:' => 'L\'essentiel (Équipes et joueurs avec photo, Tirage au sort et calendrier automatiques (championnat, groupes, aller-retour), Tableaux à élimination directe automatiques, Classement, buteurs et cartons, Suspensions automatiques et sanctions…) est inclus dans tous les forfaits. Cochez les modules inclus dans ce forfait :',
