    'Los comprobantes de' => 'Les justificatifs de',
    'Los datos' => 'Les données',
    'Los datos de menores de {n} años se tratan con especial cuidado: su inscripción requiere la autorización y los datos del representante legal, y su foto no se publica sin permiso expreso.' => 'Les données des mineurs de moins de {n} ans sont traitées avec un soin particulier : leur inscription requiert l\'autorisation et les données du représentant légal, et leur photo n\'est pas publiée sans autorisation expresse.',
    'Los datos se guardan en' => 'Les données sont stockées sur',
    'Los delegados envían desde su portal la foto de su transferencia o depósito. Revise que el dinero llegó a la cuenta y apruébelo: el pago y el recibo se registran solos. Los datos de la cuenta para pagar se escriben en' => 'Les délégués envoient depuis leur portail la photo de leur virement ou dépôt. Vérifiez que l\'argent est arrivé sur le compte et approuvez-le : le paiement et le reçu s\'enregistrent automatiquement. Les coordonnées du compte pour payer se saisissent dans',
    'Los delegados los ven al enviar el comprobante de su transferencia.' => 'Les délégués les voient lorsqu\'ils envoient le justificatif de leur virement.',
    'Los delegados piden desde su portal:' => 'Les délégués demandent depuis leur portail :',
    'Los delegados pueden inscribir jugadores hasta' => 'Les délégués peuvent inscrire des joueurs jusqu\'au',
    'Los delegados pueden pedir pases en línea' => 'Les délégués peuvent demander des transferts en ligne',
    'Los ejercicios de la escuela. El profesor los elige al planificar cada clase y los padres ven en el diario qué ejercicios hizo su hijo.' => 'Les exercices de l\'école. L\'entraîneur les choisit en planifiant chaque cours et les parents voient dans le journal quels exercices leur enfant a faits.',
    'Los equipos no tienen jugadores registrados.' => 'Les équipes n\'ont aucun joueur enregistré.',
    'Los equipos se inscriben por internet y cada delegado registra a sus jugadores.' => 'Les équipes s\'inscrivent par internet et chaque délégué enregistre ses joueurs.',
    'Los equipos se inscriben por internet; cada delegado inscribe a sus jugadores, pide pases, reprogramaciones y apelaciones y ve su estado de cuenta.' => 'Les équipes s\'inscrivent par internet ; chaque délégué inscrit ses joueurs, demande des transferts, des reports et des appels, et consulte son relevé de compte.',
    'Los equipos y los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'Les équipes et les parents paient par carte depuis leur téléphone, le reçu est émis automatiquement et vous voyez chaque paiement dans votre rapport.',
    'Los hinchas adivinan los resultados de los próximos partidos desde la página de la liga y suman puntos.' => 'Les supporters devinent les résultats des prochains matchs depuis la page de la ligue et cumulent des points.',
    'Los hinchas pronostican los resultados gratis y compiten en una tabla. Sin apuestas.' => 'Les supporters pronostiquent les résultats gratuitement et s\'affrontent dans un classement. Sans paris.',
    'Los hinchas reciben en el celular cada gol, el resultado y los horarios de su equipo.' => 'Les supporters reçoivent sur leur téléphone chaque but, le résultat et les horaires de leur équipe.',
    'Los impuestos solo se muestran desglosados en el reporte; consulte con su contador si su liga debe cobrarlos.' => 'Les taxes ne sont détaillées que dans le rapport ; consultez votre comptable pour savoir si votre ligue doit les percevoir.',
    'Los lugares donde entrenan (nombre y dirección).' => 'Les lieux où ils s\'entraînent (nom et adresse).',
    'Los límites y módulos se aplican solos a cada liga o escuela según su plan (en la prueba gratis tienen todo). {n} = sin límite. Un precio en {n} = ese período no se ofrece. En Ligas → Editar puede regalar módulos a una liga.' => 'Les limites et modules s\'appliquent automatiquement à chaque ligue ou école selon son forfait (pendant l\'essai gratuit, tout est inclus). {n} = illimité. Un prix à {n} = cette période n\'est pas proposée. Dans Ligues → Modifier, vous pouvez offrir des modules à une ligue.',
    'Los manuales de ligas y de escuelas ya están en español, inglés, francés, portugués e italiano, con todo lo nuevo. Elija el idioma con el botón 🌐.' => 'Les manuels des ligues et des écoles sont désormais disponibles en espagnol, anglais, français, portugais et italien, avec toutes les nouveautés. Choisissez la langue avec le bouton 🌐.',
    'Los marcadores en vivo se actualizan solos cada {n} segundos.' => 'Les scores en direct se mettent à jour automatiquement toutes les {n} secondes.',
    'Los módulos, uno por uno' => 'Les modules, un par un',
    'Los padres inscriben a sus hijos desde la página de la escuela.' => 'Les parents inscrivent leurs enfants depuis la page de l\'école.',
    'Los padres inscriben a sus hijos por internet y ven asistencia, pagos, recibos, evaluaciones y libreta desde el celular.' => 'Les parents inscrivent leurs enfants par internet et consultent présences, paiements, reçus, évaluations et carnet de notes depuis leur téléphone.',
    'Los padres llenan la ficha desde la página de la escuela. Llega a' => 'Les parents remplissent la fiche depuis la page de l\'école. Elle arrive à',
    'Los padres pagan con tarjeta desde su celular y el pago se aplica solo.' => 'Les parents paient par carte depuis leur téléphone et le paiement est appliqué automatiquement.',
    'Los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'Les parents paient par carte depuis leur téléphone, le reçu est émis automatiquement et vous voyez chaque paiement dans votre rapport.',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'Les parents paient par carte ; le reçu est émis automatiquement. TuAcademia vous verse les sommes encaissées moins la commission de la carte (Carte de crédit {n} % + TVA',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'Les parents paient par carte ; le reçu est émis automatiquement. TuAcademia vous verse les sommes encaissées moins la commission de la carte (Carte de crédit {n} % + TVA · Carte de débit {n} % + TVA · Gestion administrative de TuAcademia {n} %). Vous choisissez si la commission est prise en charge par votre organisation ou par le payeur.',
    'Los padres pagan las mensualidades con tarjeta de crédito o débito desde su celular; el recibo sale solo y usted ve cada pago en su reporte.' => 'Les parents paient les mensualités par carte de crédit ou de débit depuis leur téléphone ; le reçu est émis automatiquement et vous voyez chaque paiement dans votre rapport.',
    'Los padres pueden ver las fotos' => 'Les parents peuvent voir les photos',
    'Los padres ven el plan' => 'Les parents voient le plan de cours',
    'Los pases en línea solo se piden mientras la inscripción de jugadores está' => 'Les transferts en ligne ne peuvent être demandés que tant que l\'inscription des joueurs est',
    'Los pilotos con «categoría automática» entran a la primera que cumpla su cilindrada y su motor (atmosférico o turbo). Los turbo van a la categoría turbo aunque su cilindrada sea baja.' => 'Les pilotes avec « catégorie automatique » sont placés dans la première qui correspond à leur cylindrée et leur moteur (atmosphérique ou turbo). Les turbo vont dans la catégorie turbo même si leur cylindrée est faible.',
    'Los que carga el vocal en vivo aparecen aquí automáticamente.' => 'Ceux que l\'officiel de table saisit en direct apparaissent ici automatiquement.',
    'Los ven las familias en su portal y en los recibos.' => 'Les familles les voient dans leur portail et sur les reçus.',
    'Luciana Pérez Ortiz (+{n}% en promedio)' => 'Luciana Pérez Ortiz (+{n}% en moyenne)',
    'Luego el panel de la liga queda en solo lectura (la página pública sigue visible).' => 'Ensuite, le tableau de bord de la ligue passe en lecture seule (la page publique reste visible).',
