    'Mientras la persona participe en la escuela y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Tant que la personne participe à l\'école, puis le temps nécessaire pour conserver l\'historique sportif (champions, statistiques) et respecter les obligations légales (par exemple comptables et fiscales). La suppression peut être demandée à tout moment (point {n}) : dans ce cas, les données personnelles sont effacées et seules les statistiques anonymes subsistent.',
    'Mientras la persona participe en la liga y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Tant que la personne participe à la ligue, puis le temps nécessaire pour conserver l\'historique sportif (champions, statistiques) et respecter les obligations légales (par exemple comptables et fiscales). La suppression peut être demandée à tout moment (point {n}) : dans ce cas, les données personnelles sont effacées et seules les statistiques anonymes subsistent.',
    'Mientras la persona participe en la organización y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Tant que la personne participe à l\'organisation, puis le temps nécessaire pour conserver l\'historique sportif (champions, statistiques) et respecter les obligations légales (par exemple comptables et fiscales). La suppression peut être demandée à tout moment (point {n}) : dans ce cas, les données personnelles sont effacées et seules les statistiques anonymes subsistent.',
    'Mientras más afuera, mejor que el resto de su categoría en la escuela.' => 'Plus c\'est à l\'extérieur, meilleur que le reste de sa catégorie à l\'école.',
