    'Se borrarán TODOS sus equipos, jugadores, campeonatos y resultados. No se puede deshacer.' => 'TOUS ses équipes, joueurs, championnats et résultats seront supprimés. Cette action est irréversible.',
    'Se cambia en los datos del profesor.' => 'Se modifie dans les données de l\'entraîneur.',
    'Se carga a los dos equipos al jugarse el partido. En W.O. paga el doble el que no se presentó.' => 'Facturée aux deux équipes lorsque le match est joué. En cas de forfait, l\'équipe absente paie le double.',
