    'Se carga sola a cada equipo inscrito. {n} = no se cobra.' => 'Facturée automatiquement à chaque équipe inscrite. {n} = non facturé.',
    'Se cargó el derecho a examen (${n}) a {n} alumno(s). Ya aparece en Pagos y en el portal de los padres.' => 'Les frais d\'examen (${n}) ont été facturés à {n} élève(s). Ils apparaissent déjà dans Paiements et sur le portail des parents.',
    'Se cargó la lista de fábrica de {s}.' => 'La liste par défaut de {s} a été chargée.',
