    'Se cobra solo en los pagos de equipos y familias a sus ligas y escuelas.' => 'Prélevé uniquement sur les paiements des équipes et des familles à leurs ligues et écoles.',
    'Se compara con su última medición.' => 'Comparé à sa dernière mesure.',
    'Se copian las reglas de juego, puntos, tarjetas, árbitros, dinero y categoría. No se copian partidos, resultados, sanciones ni el campeón. Las fechas de inscripción en línea quedan cerradas hasta que las ponga.' => 'Les règles de jeu, points, cartons, arbitres, argent et catégorie sont copiés. Les matchs, résultats, sanctions et le champion ne sont pas copiés. Les dates d\'inscription en ligne restent fermées jusqu\'à ce que vous les définissiez.',
    'Se crea solo si lo deja vacío' => 'Créé automatiquement si vous le laissez vide',
    'Se crean solas cada mes; use esto solo para adelantar el mes siguiente.' => 'Elles sont créées automatiquement chaque mois ; utilisez ceci uniquement pour anticiper le mois suivant.',
    'Se crean solas con los datos del sistema, el logo y el color de la liga y el patrocinador (se configura en' => 'Créées automatiquement avec les données du système, le logo et la couleur de la ligue et du sponsor (se configure dans',
    'Se cuenta cada clase en la que se tomó asistencia marcando que el profesor asistió.' => 'Chaque cours pour lequel l\'appel a été fait en indiquant que l\'entraîneur était présent est compté.',
    'Se edita en la pestaña Datos → Ficha médica.' => 'Se modifie dans l\'onglet Données → Fiche médicale.',
    'Se generan solas cada mes, con becas y descuento por hermanos. Semáforo de quién está al día.' => 'Générées automatiquement chaque mois, avec bourses et remise fratrie. Feu tricolore de qui est à jour.',
