    'Se protegen según la Ley Orgánica de Protección de Datos Personales: consentimiento en la inscripción, datos de menores con autorización del representante y fotos públicas solo si se autorizan.' => 'Elles sont protégées conformément à la Loi organique de protection des données personnelles : consentement à l\'inscription, données des mineurs avec autorisation du représentant et photos publiques uniquement si elles sont autorisées.',
