    'Si considera que sus derechos no fueron atendidos, puede acudir a la Superintendencia de Protección de Datos Personales del Ecuador.' => 'Si vous estimez que vos droits n\'ont pas été respectés, vous pouvez vous adresser à la Superintendencia de Protección de Datos Personales del Ecuador.',
