    'Si la política cambia, se publicará aquí con una nueva versión. El sistema guarda qué versión aceptó cada persona.' => 'Si la politique change, elle sera publiée ici avec une nouvelle version. Le système enregistre quelle version chaque personne a acceptée.',
    'Si lo escribe, el sistema le avisa ⚠ cuando una factura esté a nombre de otra persona.' => 'Si vous le saisissez, le système vous avertit ⚠ lorsqu\'une facture est au nom d\'une autre personne.',
