    'Suba videos cortos (hasta 2 minutos) a cada jugador o alumno: les llegan a su portal para verlos y descargarlos. Se borran solos a los 10 días.' => 'Téléversez de courtes vidéos (jusqu\'à 2 minutes) pour chaque joueur ou élève : elles arrivent sur leur portail pour être vues et téléchargées. Elles s\'effacent automatiquement au bout de 10 jours.',
    'Suba videos cortos (hasta {n} minutos) de cada jugador o alumno: su gol, una jugada, su técnica. Le llegan a su portal para verlos y descargarlos; se borran solos a los {n} días.' => 'Téléversez de courtes vidéos (jusqu\'à {n} minutes) de chaque joueur ou élève : son but, une action, sa technique. Elles arrivent sur son portail pour être visionnées et téléchargées ; elles sont supprimées automatiquement après {n} jours.',
