    'Suplente' => 'Remplaçant',
    'Sus campeonatos federativos (inter-ligas) de cualquier deporte se crean en' => 'Vos championnats fédéraux (inter-ligues) de n\'importe quel sport se créent dans',
    'Sus datos' => 'Vos données',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA' => 'Vos équipes paient par carte de crédit ou de débit depuis leur mobile. TuAcademia reçoit l\'argent via Plux, applique le paiement, émet le reçu instantanément et vous transfère les sommes encaissées sur votre compte. Coût : Carte de crédit {n}% + TVA',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%.' => 'Vos équipes paient par carte de crédit ou de débit depuis leur mobile. TuAcademia reçoit l\'argent via Plux, applique le paiement, émet le reçu instantanément et vous transfère les sommes encaissées sur votre compte. Coût : Carte de crédit {n}% + TVA · Carte de débit {n}% + TVA · Gestion administrative de TuAcademia {n}%.',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Vos équipes paient par carte de crédit ou de débit ; le reçu est émis automatiquement et vous recevez le virement sur votre compte. Coût par transaction : Carte de crédit {n}% + TVA',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Vos équipes paient par carte de crédit ou de débit ; le reçu est émis automatiquement et vous recevez le virement sur votre compte. Coût par transaction : Carte de crédit {n}% + TVA · Carte de débit {n}% + TVA · Gestion administrative de TuAcademia {n}%. Vous choisissez si la commission est supportée par votre organisation ou par celui qui paie.',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'Vos équipes paient par carte ; le reçu est émis automatiquement. TuAcademia vous transfère les sommes encaissées moins la commission de la carte (Carte de crédit {n}% + TVA',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'Vos équipes paient par carte ; le reçu est émis automatiquement. TuAcademia vous transfère les sommes encaissées moins la commission de la carte (Carte de crédit {n}% + TVA · Carte de débit {n}% + TVA · Gestion administrative de TuAcademia {n}%). Vous choisissez si la commission est supportée par votre organisation ou par celui qui paie.',
    'Sus equipos pagan inscripciones, arbitrajes y multas con' => 'Vos équipes paient inscriptions, arbitrages et amendes avec',
    'Sus equipos y familias le pagan con tarjeta de crédito o débito desde su celular; el sistema aplica el pago, emite el recibo y usted ve todo en su reporte de pagos.' => 'Vos équipes et familles vous paient par carte de crédit ou de débit depuis leur mobile ; le système applique le paiement, émet le reçu et vous voyez tout dans votre rapport des paiements.',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Vos familles paient par carte de crédit ou de débit ; le reçu est émis automatiquement et vous recevez le virement sur votre compte. Coût par transaction : Carte de crédit {n}% + TVA',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Vos familles paient par carte de crédit ou de débit ; le reçu est émis automatiquement et vous recevez le virement sur votre compte. Coût par transaction : Carte de crédit {n}% + TVA · Carte de débit {n}% + TVA · Gestion administrative de TuAcademia {n}%. Vous choisissez si la commission est supportée par votre organisation ou par celui qui paie.',
    'Sus familias pagan las mensualidades con' => 'Vos familles paient les mensualités avec',
    'Sus goles y tarjetas anteriores quedan con su equipo anterior. El sistema revisa el cupo y la categoría del equipo que lo recibe.' => 'Ses buts et cartons précédents restent avec son ancienne équipe. Le système vérifie le quota et la catégorie de l\'équipe qui le reçoit.',
