    'Sí, cuando quiera, desde "Mi plan" en su panel. Los módulos nuevos se activan al instante y no pierde ningún dato.' => 'Oui, quand vous voulez, depuis « Mon forfait » dans votre tableau de bord. Les nouveaux modules sont activés instantanément et vous ne perdez aucune donnée.',
    'Sí:' => 'Oui :',
    'Sí: cada liga y cada campeonato tienen su dirección corta ({n}:{n}/su-liga/apertura) y, pagando el plan Profesional por {n} año, le damos un dominio propio (www.suliga.com).' => 'Oui : chaque ligue et chaque championnat ont leur adresse courte ({n}:{n}/su-liga/apertura) et, en souscrivant le forfait Professionnel pour {n} an, nous vous offrons un domaine propre (www.suliga.com).',
    'Sí: fútbol {n}, {n}, {n}, {n}, {n}, {n} o personalizado, indor, ecuavóley por sets y básquet. Cada campeonato define sus jugadores, tiempos, árbitros y reglas.' => 'Oui : football {n}, {n}, {n}, {n}, {n}, {n} ou personnalisé, futsal, ecuavóley par sets et basket. Chaque championnat définit ses joueurs, ses temps, ses arbitres et ses règles.',
    'Sí: su escuela tiene su dirección corta ({n}:{n}/su-escuela) y, pagando el plan Escuela Completo por {n} año, le damos un dominio propio (www.suescuela.com).' => 'Oui : votre école a son adresse courte ({n}:{n}/su-escuela) et, en souscrivant le forfait École Complet pour {n} an, nous vous offrons un domaine propre (www.suescuela.com).',
