    'Una jornada de evaluación es el día (o la semana) en que se toman los tests a todos. Se crea una vez con los tests elegidos y cada profesor la llena desde el celular en el entrenamiento. Así todos los alumnos quedan medidos con la misma fecha y se comparan con la jornada anterior.' => 'Une journée d\'évaluation est le jour (ou la semaine) où l\'on fait passer les tests à tous. Elle se crée une fois avec les tests choisis et chaque entraîneur la remplit depuis son téléphone à l\'entraînement. Ainsi, tous les élèves sont mesurés à la même date et comparés à la journée précédente.',
