    'Venda espacios a empresas del barrio:' => 'Vendez des espaces aux entreprises du quartier :',
    'Venda espacios a empresas del barrio: su banner sale en la página pública de la liga, en los partidos ("Partido presentado por…"), en las imágenes para redes y en los carnets. El sistema cuenta cuántas veces se mostró su marca y cuántos clics recibió: imprima el' => 'Vendez des espaces aux entreprises du quartier : leur bannière apparaît sur la page publique de la ligue, dans les matchs (« Match présenté par… »), dans les images pour les réseaux et sur les cartes. Le système compte combien de fois leur marque a été affichée et combien de clics elle a reçus : imprimez le',
    'Venda las entradas de sus partidos por internet (tarjeta o transferencia), en taquilla y cortesías, con parqueadero opcional. Cada entrada tiene su QR y en la puerta se valida con el celular, aunque no haya internet.' => 'Vendez les billets de vos matchs sur internet (carte ou virement), au guichet et en invitations, avec parking en option. Chaque billet a son QR et à l\'entrée il est validé avec le mobile, même sans internet.',
    'Venda por adelantado las entradas de sus partidos, también a los hinchas. Cada entrada tiene su QR y en la puerta se valida con el celular. Si no marca la casilla, no aparece nada de esto.' => 'Vendez à l\'avance les billets de vos matchs, y compris aux supporters. Chaque billet a son QR et à l\'entrée il est validé avec le mobile. Si vous ne cochez pas la case, rien de tout cela n\'apparaît.',
