    'del comprobante y envíe. Lo revisamos y su cuenta queda activa el mismo día, con todo lo que ya cargó.' => 'du justificatif et envoyez. Nous le vérifions et votre compte est activé le jour même, avec tout ce que vous avez déjà saisi.',
