    ': lo activamos el mismo día.' => ' : nous l\'activons le jour même.',
    '¿Dudas?' => 'Des questions ?',
    '¡Recibimos su comprobante! Lo revisamos y le avisamos por correo y Telegram apenas quede activa su cuenta (normalmente el mismo día).' => 'Nous avons reçu votre justificatif ! Nous le vérifions et vous prévenons par e-mail et Telegram dès que votre compte est actif (généralement le jour même).',
    'Ya tiene un comprobante por revisar. Le avisamos apenas lo aprobemos (normalmente el mismo día).' => 'Vous avez déjà un justificatif en cours de vérification. Nous vous préviendrons dès son approbation (généralement le jour même).',
    'Adjunte la foto o captura del comprobante de la transferencia (JPG o PNG).' => 'Joignez la photo ou la capture du justificatif de virement (JPG ou PNG).',
    'Elija el plan que quiere contratar.' => 'Choisissez le forfait que vous souhaitez souscrire.',
    'Elija por cuánto tiempo va a pagar.' => 'Choisissez pour quelle durée vous payez.',
    'Solo el administrador puede contratar o renovar el plan.' => 'Seul l\'administrateur peut souscrire ou renouveler le forfait.',
    'Su demo terminó el {n}-{n}-{n}. El panel está en solo lectura: contrate su plan en Mi plan y sigue con todo lo que cargó.' => 'Votre démo s\'est terminée le {n}-{n}-{n}. Le tableau de bord est en lecture seule : souscrivez votre forfait dans Mon forfait et continuez avec tout ce que vous avez saisi.',
    '💵 Contratar mi plan' => '💵 Souscrire mon forfait',
    '💵 Renovar ahora' => '💵 Renouveler maintenant',
    '📤 Contratar mi plan y subir el comprobante' => '📤 Souscrire mon forfait et téléverser le justificatif',
    '📤 Renovar y subir el comprobante' => '📤 Renouveler et téléverser le justificatif',
    '💵 Contrate o renueve sin salir del sistema' => '💵 Souscrivez ou renouvelez sans quitter le système',
    'En ⭐ Mi plan ahora puede elegir su plan, transferir y subir la foto del comprobante. Lo revisamos y su cuenta queda activa el mismo día; le avisamos por correo y Telegram. Si está en demo, al contratar sigue con todo lo que ya cargó.' => 'Dans ⭐ Mon forfait vous pouvez désormais choisir votre forfait, virer et téléverser la photo du justificatif. Nous le vérifions et votre compte est activé le jour même ; nous vous prévenons par e-mail et Telegram. Si vous êtes en démo, en souscrivant vous gardez tout ce que vous avez saisi.',
    '✉️ Avisos por correo' => '✉️ Notifications par e-mail',
    'Además de Telegram, ahora recibe por correo la bienvenida con sus accesos, los avisos de vencimiento y la confirmación de cada pago. Revise que el correo de contacto de su cuenta esté bien (Parámetros).' => 'En plus de Telegram, vous recevez désormais par e-mail la bienvenue avec vos accès, les avis d\'échéance et la confirmation de chaque paiement. Vérifiez que l\'e-mail de contact de votre compte est correct (Paramètres).',
