    'Carrera de un día: 1. Vuelta por etapas: el número de etapas. Cada carrera puede tener las suyas.' => 'Course d\'un jour : 1. Course par étapes : le nombre d\'étapes. Chaque course peut avoir les siennes.',
    'XCO: 1. Descenso: normalmente 2 bajadas. Enduro: los tramos. Cada carrera puede tener las suyas.' => 'XCO : 1. Descente : normalement 2 manches. Enduro : les spéciales. Chaque course peut avoir les siennes.',
    'Mejor joven: hasta cuántos años' => 'Meilleur jeune : jusqu\'à quel âge',
    'UCI: sub-23 = hasta 22 años cumplidos en el año. 0 = sin clasificación del joven.' => 'UCI : moins de 23 ans = jusqu\'à 22 ans atteints dans l\'année. 0 = pas de classement du jeune.',
