    'Escríbalo igual para todos los del mismo equipo (cuenta para la clasificación por equipos).' => 'Écrivez-le de la même façon pour tous ceux de la même équipe (compte pour le classement par équipes).',
    'Vueltas de la carrera (XCO)' => 'Tours de la course (XCO)',
    '0 = se toma la mayor cantidad de vueltas que alguien completó.' => '0 = on prend le plus grand nombre de tours accomplis.',
