    'Fuera de control: % sobre el tiempo del ganador (0 = sin límite)' => 'Délai : % sur le temps du vainqueur (0 = sans limite)',
    'Segundos que se restan al 1.°, 2.°, 3.° en la meta' => 'Secondes retirées au 1er, 2e, 3e à l\'arrivée',
