    'Guardar etapas' => 'Enregistrer les étapes',
    'En línea:' => 'En ligne :',
    'llegada normal con bonificaciones (UCI: 10-6-4 s) y mismo tiempo para el grupo.' => 'arrivée normale avec bonifications (UCI : 10-6-4 s) et même temps pour le peloton.',
    'Contrarreloj individual:' => 'Contre-la-montre individuel :',
    'sin bonificaciones.' => 'sans bonifications.',
    'Contrarreloj por equipos:' => 'Contre-la-montre par équipes :',
    'el tiempo del equipo se toma en su 3.er corredor.' => 'le temps de l\'équipe est pris sur son 3e coureur.',
    'Critérium:' => 'Critérium :',
    'gana quien suma más puntos. Límite %: los que llegan más allá de ese porcentaje del tiempo del ganador quedan fuera de control (OTL) y salen de la general (UCI usa entre 8 % y 20 % según la etapa).' => 'celui qui a le plus de points gagne. Délai % : ceux qui arrivent au-delà de ce pourcentage du temps du vainqueur sont hors délai (OTL) et quittent le général (l\'UCI utilise de 8 % à 20 % selon l\'étape).',
    'Ruta:' => 'Route :',
    'escriba el tiempo real de llegada de cada uno; el sistema aplica solo el mismo tiempo del grupo, las bonificaciones de meta, los puntos y el fuera de control según la configuración de cada etapa. En ⚑ cargue las bonificaciones y puntos de los sprints intermedios y los puntos de montaña.' => 'écrivez le temps réel d\'arrivée de chacun ; le système applique seul le même temps du peloton, les bonifications, les points et les délais selon la configuration de chaque étape. Dans ⚑ saisissez les bonifications et points des sprints intermédiaires et les points de montagne.',
    'XCO:' => 'XCO :',
    'en «vueltas» ponga las vueltas que completó; si el comisario lo retiró por la regla del 80 % o fue doblado, ponga su tiempo y sus vueltas (queda clasificado detrás, con «−N vueltas»).' => 'dans « tours » indiquez les tours accomplis ; si le commissaire l\'a retiré par la règle des 80 % ou s\'il a été doublé, indiquez son temps et ses tours (il est classé derrière, avec « −N tours »).',
