    'Reglas de la UCI: la general suma los tiempos de las etapas menos las bonificaciones; los que llegan en el mismo grupo (menos de 1 s) reciben el mismo tiempo (m.t.). OTL: fuera de control · DNF: no terminó · DSQ: descalificado · DNS: no largó.' => 'Règles UCI : le général additionne les temps des étapes moins les bonifications ; ceux qui arrivent dans le même groupe (moins d\'1 s) reçoivent le même temps (m.t.). OTL : hors délai · DNF : abandon · DSQ : disqualifié · DNS : non partant.',
