    'Elija quién ganó cada manga; la 3.ª solo si van 1 a 1. Cuando una ronda termina, el sistema arma la siguiente.' => 'Choisissez qui a gagné chaque manche ; la 3e seulement à 1-1. Quand un tour se termine, le système crée le suivant.',
