    'Ruta: etapas en línea, contrarreloj y critérium, bonificaciones, mismo tiempo del grupo, fuera de control y clasificaciones de puntos, montaña, mejor joven y equipos. Nuevos deportes: ciclismo de pista (velocidad, keirin, persecución, puntos, scratch, eliminación, tempo y omnium), BMX Racing (motos, cuartos, semis y final), BMX Freestyle (Park y Flatland con jueces) y MTB (cross-country por vueltas, descenso y enduro).' => 'Route : étapes en ligne, contre-la-montre et critériums, bonifications, même temps du peloton, délais et classements par points, montagne, meilleur jeune et équipes. Nouveaux sports : cyclisme sur piste (vitesse, keirin, poursuite, points, scratch, élimination, tempo et omnium), BMX Racing (manches, quarts, demies et finale), BMX Freestyle (Park et Flatland avec juges) et VTT (cross-country aux tours, descente et enduro).',
