    'Ficha de la federación' => 'Fiche de la fédération',
    'El sistema ahora se arma por deporte: Fútbol, Básquet, Vóley, Ecuavóley, Ciclismo, Deportes de combate, Deportes de raqueta, Natación, Atletismo, Bolos y Automovilismo. Agregue a su cuenta los deportes que necesite con descuento desde el segundo módulo; todo queda en el mismo panel. Cada deporte pide sus propios datos y documentos (licencia, certificado médico, peso, grado…).' => 'Le système se compose désormais par sport : Football, Basket-ball, Volley-ball, Ecuavolley, Cyclisme, Sports de combat, Sports de raquette, Natation, Athlétisme, Bowling et Sport automobile. Ajoutez à votre compte les sports dont vous avez besoin avec une remise dès le deuxième module ; tout reste dans le même panneau. Chaque sport demande ses propres données et documents (licence, certificat médical, poids, grade…).',
    // (v35) módulos separados
    'Deportes de raqueta' => 'Sports de raquette',
    'Automovilismo' => 'Sport automobile',
    'Tenis, pádel y tenis de mesa: llaves con cabezas de serie, marcador por sets, todos contra todos y ranking.' => 'Tennis, padel et tennis de table : tableaux avec têtes de série, score par sets, poules et classement.',
    'Pruebas por estilo y distancia (libre, espalda, pecho, mariposa, combinado y relevos), por edad y rama, con medallero y puntos por club.' => 'Épreuves par nage et distance (libre, dos, brasse, papillon, 4 nages et relais), par âge et sexe, avec médailles et points par club.',
    'Carreras, vallas, saltos, lanzamientos y relevos por categoría y rama, con medallero, puntos por club y mejores marcas.' => 'Courses, haies, sauts, lancers et relais par catégorie et sexe, avec médailles, points par club et meilleures performances.',
    'Jornadas con líneas, handicap automático, récords y clasificación individual y por clubes.' => 'Journées avec parties, handicap automatique, records et classements individuel et par club.',
    'Autocross por mangas con categorías por cilindrada y motor, conos, penalizaciones y campeonato por puntos o tiempo.' => 'Autocross par manches avec catégories par cylindrée et moteur, cônes, pénalités et championnat aux points ou au temps.',
    'Licencia de piloto' => 'Licence de pilote',
    'Licencia de conducir' => 'Permis de conduire',
    'Revisión técnica del vehículo' => 'Contrôle technique du véhicule',
