    'Carreras de ruta, trail y cross' => 'Courses sur route, trail et cross',
    'Atletismo, Carreras de ruta, trail y cross' => 'Athlétisme, Courses sur route, trail et cross',
    'Tenis, Pádel, Tenis de mesa, Squash' => 'Tennis, Padel, Tennis de table, Squash',
    'Tenis, pádel, tenis de mesa y squash: llaves con cabezas de serie, grupos, consolación, Monrad, escalera del club, marcador por sets o games a 11 y ranking del circuito.' => 'Tennis, padel, tennis de table et squash : tableaux avec têtes de série, poules, consolante, Monrad, échelle du club, score par sets ou jeux en 11 et classement du circuit.',
    'Torneos por sistema suizo (Buchholz), todos contra todos o llave, con ELO, categorías Sub 10 a Sub 18 y ranking del circuito.' => 'Tournois au système suisse (Buchholz), toutes rondes ou à élimination, avec Elo, catégories U10 à U18 et classement du circuit.',
    'Torneos de videojuegos 1 vs 1 o 2 vs 2 (eFootball, FIFA/FC y otros): grupos, llaves con penales, tabla por goles y ranking.' => 'Tournois de jeux vidéo 1 contre 1 ou 2 contre 2 (eFootball, FIFA/FC et autres) : poules, tableaux avec tirs au but, classement par buts et classement général.',
    'Competencias con las reglas de la IWF: categorías de peso corporal, 3 intentos de arranque y 3 de envión, total, medallero y puntos por club.' => 'Compétitions avec les règles de l\'IWF : catégories de poids, 3 essais à l\'arraché et 3 à l\'épaulé-jeté, total, tableau des médailles et points par club.',
    'Triatlón, duatlón y acuatlón: tiempo por segmento y transiciones, clasificación general, por rama y por grupo de edad.' => 'Triathlon, duathlon et aquathlon : temps par segment et transitions, classement général, par sexe et par groupe d\'âge.',
    'Balonmano (handball) 7 contra 7: goles, goles de 7 metros, exclusiones de 2 minutos, amonestaciones y descalificaciones, vocalía en vivo, tabla 2-1-0 y goleadores.' => 'Handball 7 contre 7 : buts, buts à 7 mètres, exclusions de 2 minutes, avertissements et disqualifications, feuille de match en direct, classement 2-1-0 et buteurs.',
    'Béisbol (9 entradas) y softbol (7 entradas): carreras por entrada, hits, errores, jonrones y ponches, pizarra del partido, vocalía en vivo y tabla de ganados.' => 'Baseball (9 manches) et softball (7 manches) : points par manche, coups sûrs, erreurs, coups de circuit et retraits sur prises, tableau du match, feuille en direct et classement des victoires.',
    'Pista y campo con las reglas de World Athletics (series y final, viento, concursos con intentos, salto alto y garrocha por alturas, heptatlón y decatlón) y carreras de ruta, trail y cross con tiempo de chip, grupos de edad, diplomas y equipos.' => 'Piste et concours avec les règles de World Athletics (séries et finale, vent, concours avec essais, hauteur et perche par barres, heptathlon et décathlon) et courses sur route, trail et cross avec puce, groupes d\'âge, diplômes et équipes.',
    'Squash · Games a 11: grupos y luego llave, Monrad con todos los puestos, escalera del club y ranking.' => 'Squash · Jeux en 11 : poules puis tableau, Monrad avec toutes les places, échelle du club et classement.',
    'Ajedrez · Sistema suizo con Buchholz, ELO y todos contra todos.' => 'Échecs · Système suisse avec Buchholz, Elo et toutes rondes.',
    'E-sports · eFootball 1 vs 1: grupos, llave con penales y tercer puesto.' => 'E-sport · eFootball 1 contre 1 : poules, tableau avec tirs au but et 3e place.',
    'Carreras de ruta, trail y cross · 10K con tiempo de chip, grupos de edad, equipos, buscador por dorsal y diplomas.' => 'Courses sur route, trail et cross · 10 km avec puce, groupes d\'âge, équipes, recherche par dossard et diplômes.',
    'Levantamiento de pesas · Arranque y envión con 3 intentos, total y peso corporal (IWF).' => 'Haltérophilie · Arraché et épaulé-jeté en 3 essais, total et poids de corps (IWF).',
    'Triatlón · Natación, transiciones, ciclismo y carrera, con grupos de edad.' => 'Triathlon · Natation, transitions, vélo et course, avec groupes d\'âge.',
    'Grupos y luego llave' => 'Poules puis tableau',
    'Llave con consolación' => 'Tableau avec consolante',
    'Llave con todos los puestos (Monrad)' => 'Tableau avec toutes les places (Monrad)',
    'Sistema suizo (por rondas)' => 'Système suisse (par rondes)',
    'Escalera de desafíos (ranking del club)' => 'Échelle de défis (classement du club)',
    'El que pierde queda fuera. Cabezas de serie separados y pases directos repartidos.' => 'Le perdant est éliminé. Têtes de série séparées et exemptions réparties.',
    'Todos juegan contra todos; gana la tabla.' => 'Tout le monde joue contre tout le monde ; le classement décide.',
    'Grupos de 3 a 5 (todos contra todos) y los primeros de cada grupo pasan a una llave final. Es el formato de los nacionales de squash.' => 'Poules de 3 à 5 (toutes rondes) ; les premiers de chaque poule vont dans un tableau final. C\'est le format des championnats nationaux de squash.',
    'Llave principal y una llave de consolación (plate) para los que pierden su primer partido: todos juegan al menos dos.' => 'Tableau principal et une consolante (plate) pour ceux qui perdent leur premier match : chacun joue au moins deux matchs.',
    'Nadie queda fuera: ganadores y perdedores siguen jugando en sub-llaves hasta definir todos los puestos (1.º al último).' => 'Personne n\'est éliminé : gagnants et perdants continuent dans des sous-tableaux jusqu\'à classer tout le monde (du 1er au dernier).',
    'Por rondas: en cada ronda se empareja a los de igual puntaje sin repetir rival. Ideal para ajedrez y para muchos inscritos.' => 'Par rondes : chaque ronde apparie les joueurs de même score sans répéter d\'adversaire. Idéal pour les échecs et les grands tableaux.',
    'Ranking permanente del club: se desafía a alguien hasta N puestos arriba; si gana, toma su puesto.' => 'Classement permanent du club : on défie quelqu\'un jusqu\'à N places au-dessus ; en gagnant, on prend sa place.',
    'Grupos: jugadores por grupo' => 'Poules : joueurs par poule',
    'Grupos: pasan a la llave' => 'Poules : qualifiés pour le tableau',
    'Solo «Grupos y luego llave». Squash: 3 (máximo 5).' => 'Seulement « Poules puis tableau ». Squash : 3 (maximum 5).',
    'Los primeros de cada grupo.' => 'Les premiers de chaque poule.',
    'Suizo: rondas' => 'Suisse : rondes',
    'Vacío = según los inscritos (8 → 4 rondas).' => 'Vide = selon les inscrits (8 → 4 rondes).',
    'Escalera: desafiar hasta' => 'Échelle : défier jusqu\'à',
