    'El ranking aparece cuando termina al menos una categoría de un campeonato (la final jugada o todas las fechas).' => 'Le classement apparaît quand au moins une catégorie d\'un championnat est terminée (finale jouée ou toutes les journées).',
    'Suma los puntos de todos los campeonatos de {s} de su cuenta, por categoría (mismo nombre de categoría). Cada campeonato da puntos según el puesto final, multiplicados por su factor (por ejemplo: nacional 100 %, regional 50 %). Se cambian en «Reglas y configuración».' => 'Additionne les points de tous vos championnats de {s}, par catégorie (même nom). Chaque championnat donne des points selon la place finale, multipliés par son coefficient (ex. : national 100 %, régional 50 %). Ils se modifient dans « Règles et configuration ».',
