    'Se puede desafiar hasta {n} puestos más arriba. Si gana el retador, toma el puesto del desafiado y los de en medio bajan uno.' => 'On peut défier jusqu\'à {n} places au-dessus. Si le challenger gagne, il prend la place du défié et ceux du milieu descendent d\'une place.',
    'Toque un partido para cargar su resultado o programarlo. Al terminar los grupos se arma sola la llave final.' => 'Touchez un match pour saisir son résultat ou le programmer. À la fin des poules, le tableau final se crée tout seul.',
    'Al sortear, los cabezas de serie quedan separados, se reparten los pases directos y se evita que dos del mismo club se crucen al inicio.' => 'Au tirage, les têtes de série sont séparées, les exemptions réparties et deux joueurs du même club ne se rencontrent pas au début.',
