    'si pasó. Gana la mejor marca; si empatan, decide la segunda mejor.' => 'en cas de passage. La meilleure marque gagne ; en cas d\'égalité, la deuxième meilleure décide.',
    'si pasó. Después de {n} intentos, los {n} mejores hacen {n} más (sus casillas se marcan en verde). Gana la mejor marca; si empatan, decide la segunda mejor.' => 'en cas de passage. Après {n} essais, les {n} meilleurs en font {n} de plus (leurs cases sont en vert). La meilleure marque gagne ; en cas d\'égalité, la deuxième meilleure décide.',
    'si pasó. Después de {n} intentos, los {n} mejores hacen {n} más (sus casillas se marcan en verde). Gana la mejor marca; si empatan, decide la segunda mejor. Debajo de cada marca, el viento (ej: +{n}).' => 'en cas de passage. Après {n} essais, les {n} meilleurs en font {n} de plus (leurs cases sont en vert). La meilleure marque gagne ; en cas d\'égalité, la deuxième meilleure décide. Sous chaque marque, le vent (ex. : +{n}).',
    'Salto alto y garrocha (World Athletics)' => 'Saut en hauteur et perche (World Athletics)',
    'en cada altura escriba lo que hizo:' => 'à chaque hauteur écrivez le résultat :',
    'pasó al {n}.º,' => 'franchi au {n}er essai,',
