    'quedó eliminado,' => 'éliminé,',
    'y luego pasó a la siguiente (' => 'puis passe à la hauteur suivante (',
    'si no saltó esa altura. Gana la mayor altura; si empatan, el de menos intentos en esa altura y luego el de menos fallos en todo el concurso.' => 'si la hauteur n\'a pas été tentée. La plus grande hauteur gagne ; en cas d\'égalité, le moins d\'essais à cette hauteur, puis le moins d\'échecs dans tout le concours.',
    'Heptatlón (tabla de puntos de World Athletics)' => 'Heptathlon (table de points de World Athletics)',
