    'Pesas (IWF)' => 'Haltérophilie (IWF)',
    'escriba el peso corporal del pesaje y los kilos de cada intento:' => 'écrivez le poids de corps de la pesée et les kilos de chaque essai :',
    'escriba el peso corporal del pesaje (hasta {n} kg) y los kilos de cada intento:' => 'écrivez le poids de corps de la pesée (jusqu\'à {n} kg) et les kilos de chaque essai :',
    'escriba el peso corporal del pesaje (más de {n} kg) y los kilos de cada intento:' => 'écrivez le poids de corps de la pesée (plus de {n} kg) et les kilos de chaque essai :',
    'si fue válido,' => 'si réussi,',
