    'El total que paga el cliente = precio del plan (Básico, Profesional…) + lo de esta columna. En {n} y {n} meses se aplica la misma rebaja del plan (meses gratis).' => 'Le total payé par le client = prix de la formule (Basique, Professionnel…) + cette colonne. Sur {n} et {n} mois, la même remise que la formule s\'applique (mois gratuits).',
    'Son los valores con los que empieza cada campeonato nuevo de este deporte en todas las cuentas. Deje vacío para usar el valor de fábrica (entre paréntesis). Cada cuenta puede cambiarlos después en su campeonato.' => 'Ce sont les valeurs de départ de chaque nouveau championnat de ce sport dans tous les comptes. Laissez vide pour la valeur d\'usine (entre parenthèses). Chaque compte peut les modifier ensuite dans son championnat.',
    '— de fábrica —' => '— d\'usine —',
    'Nombre, cédula, foto, fecha de nacimiento y club ya están en cada ficha: aquí van los datos propios del deporte.' => 'Nom, pièce d\'identité, photo, date de naissance et club sont déjà sur chaque fiche : ici vont les données propres au sport.',
    'Nuevo documento (ej: Ficha de la federación)' => 'Nouveau document (ex. : fiche de la fédération)',
    'Para quitar un documento, borre su nombre. Con «tiene vencimiento» se pide la fecha y, cuando pasa, vuelve a aparecer como faltante (ej: certificado médico anual).' => 'Pour retirer un document, effacez son nom. Avec « expire », la date est demandée et, une fois passée, il réapparaît comme manquant (ex. : certificat médical annuel).',
    'Se piden en la ficha del jugador, del competidor o del alumno de este deporte y en la inscripción en línea. Lo' => 'Ils sont demandés sur la fiche du joueur, du compétiteur ou de l\'élève de ce sport et dans l\'inscription en ligne. Ce',
    'que falte aparece como «⚠ falta» en las listas, y en la inscripción en línea no se puede enviar sin eso.' => 'qui manque apparaît comme « ⚠ manque » dans les listes, et l\'inscription en ligne ne peut pas être envoyée sans cela.',
    'Para que el panel siga funcionando sin interrupciones, renueve antes de esa fecha.' => 'Pour que le panneau continue de fonctionner sans interruption, renouvelez avant cette date.',
    '⏰ Su suscripción de TuAcademia vence en {s} días ({s})' => '⏰ Votre abonnement TuAcademia expire dans {s} jours ({s})',
    'Activa hasta el {s} (faltan {s} días)' => 'Actif jusqu\'au {s} (reste {s} jours)',
    'Puede crear {n} campeonato a la vez (en curso) · lleva {n} · no le quedan más' => 'Vous pouvez créer {n} championnat à la fois (en cours) · vous en avez {n} · plus aucun disponible',
    'El sistema se vende por deporte. Cada cuenta tiene sus módulos; quien compra más de uno lo ve todo junto en el mismo panel. Aquí maneja precios, requisitos, reglas por defecto, qué módulos tiene cada cuenta y las demos de cada deporte.' => 'Le système se vend par sport. Chaque compte a ses modules ; qui en achète plusieurs voit tout ensemble dans le même panneau. Ici vous gérez les prix, les exigences, les règles par défaut, les modules de chaque compte et les démos de chaque sport.',
    '(natación, atletismo, ciclismo de pista, bmx racing, bmx freestyle, carreras de ruta, trail y cross, levantamiento de pesas, triatlón, duatlón y acuatlón)' => '(natation, athlétisme, cyclisme sur piste, BMX racing, BMX freestyle, courses sur route, trail et cross, haltérophilie, triathlon, duathlon et aquathlon)',
    '(tenis, pádel, tenis de mesa, squash, artes marciales, boxeo, ajedrez, e-sports)' => '(tennis, padel, tennis de table, squash, arts martiaux, boxe, échecs, e-sport)',
    '(Fútbol, Indor, Ecuavóley, Básquet, Balonmano, Béisbol y softbol)' => '(Football, Futsal, Ecuavolley, Basket, Handball, Baseball et softball)',
    'Béisbol, Softbol' => 'Baseball, Softball',
    'Boxeo, Artes marciales' => 'Boxe, Arts martiaux',
    'Básquet 5×5, Básquet 3×3' => 'Basket 5×5, Basket 3×3',
    'Taekwondo' => 'Taekwondo',
    '🥋 Judo' => '🥋 Judo',
    '🥋 Taekwondo' => '🥋 Taekwondo',
    '· Carrera con clasificación general, por rama y por edad.' => '· Course avec classement général, par sexe et par âge.',
    'en demo · 🏆 {n} campeonatos · 🎓 {n} grupos' => 'en démo · 🏆 {n} championnats · 🎓 {n} groupes',
    '· {n} campeonato' => '· {n} championnat',
