    '/mes · {n} modalidades · {n} datos y {n} documentos pedidos' => '/mois · {n} disciplines · {n} données et {n} documents demandés',
    'Varones Libre' => 'Hommes Open',
    'Precios en dólares. En la demo tiene todos los módulos (el fixture para imprimir y el esquema del campeonato son exclusivos del plan Profesional). ¿Necesita algo especial? Consúltenos.' => 'Prix en dollars. La démo a tous les modules (le calendrier à imprimer et le schéma du championnat sont réservés à la formule Professionnel). Besoin de quelque chose de spécial ? Contactez-nous.',
    '· 🎓 Escuela multideporte (fútbol, básquet, vóley, boxeo, natación, taekwondo y tenis) ·' => '· 🎓 École multisport (football, basket, volley, boxe, natation, taekwondo et tennis) ·',
    'usa las reglas de la UCI (etapas, mismo tiempo, bonificaciones, puntos, montaña, mejor joven y equipos); en' => 'utilise les règles de l\'UCI (étapes, même temps, bonifications, points, montagne, meilleur jeune et équipes) ; en',
    ', XCO por vueltas, descenso y enduro. Para pista y BMX use «campeonato por pruebas».' => ', XCO par tours, descente et enduro. Pour la piste et le BMX utilisez « championnat par épreuves ».',
    'Aún no hay registros de goles.' => 'Aucun but enregistré pour l\'instant.',
