    'Fútbol, indor, vóley, ecuavóley, básquet, balonmano, béisbol y deportes individuales: carreras, tenis, pádel, squash, tenis de mesa, artes marciales, boxeo, ajedrez, e-sports, bolos, natación, atletismo, carreras de ruta, pesas y triatlón; y olimpiadas multideportivas.' => 'Football, futsal, volley, ecuavolley, basket, handball, baseball et sports individuels : courses, tennis, padel, squash, tennis de table, arts martiaux, boxe, échecs, e-sport, bowling, natation, athlétisme, courses sur route, haltérophilie et triathlon ; et olympiades multisports.',
    // v37
    'Olimpiadas' => 'Olympiades',
    '🏅 Olimpiadas' => '🏅 Olympiades',
    'Olimpiadas y juegos multideportivos' => 'Olympiades et jeux multisports',
    'Olimpiadas interempresas, interbancarias o intercolegiales: varios deportes a la vez, delegaciones que inscriben a su gente con su propio enlace, una ficha por deportista, medallero general, tabla de puntos configurable y administradores por evento.' => 'Olympiades inter-entreprises, interbancaires ou interscolaires : plusieurs sports à la fois, des délégations qui inscrivent leurs membres avec leur propre lien, une fiche par sportif, un tableau des médailles général, un classement par points configurable et des administrateurs par événement.',
    'Juegos multideportivos: delegaciones y medallero' => 'Jeux multisports : délégations et médailles',
    'Eventos multideportivos: disciplinas, delegaciones, deportistas, medallero y configuración.' => 'Événements multisports : disciplines, délégations, sportifs, médailles et configuration.',
    'Administrador de evento (olimpiadas)' => 'Administrateur d\'événement (olympiades)',
    'Solo los eventos de olimpiadas que se le asignan: configuración, disciplinas, delegaciones, deportistas, resultados de sus campeonatos y medallero.' => 'Seulement les olympiades qui lui sont attribuées : configuration, disciplines, délégations, sportifs, résultats de leurs championnats et médailles.',
    'Administrador de evento (olimpiadas) — Solo los eventos de olimpiadas que se le asignan: configuración, disciplinas, delegaciones, deportistas, resultados de sus campeonatos y medallero.' => 'Administrateur d\'événement (olympiades) — Seulement les olympiades qui lui sont attribuées : configuration, disciplines, délégations, sportifs, résultats de leurs championnats et médailles.',
    '🏅 Olimpiadas y juegos multideportivos' => '🏅 Olympiades et jeux multisports',
    'Organice olimpiadas interempresas, interbancarias, intercolegiales o de barrio: varios deportes a la vez, cada empresa o colegio como una' => 'Organisez des olympiades inter-entreprises, interbancaires, interscolaires ou de quartier : plusieurs sports à la fois, chaque entreprise ou école comme une',
    'delegación' => 'délégation',
    'que inscribe a su gente con su propio enlace, un' => 'qui inscrit ses membres avec son propre lien, un',
    'medallero general' => 'tableau des médailles général',
    'tabla de puntos' => 'classement par points',
