    '✓ terminó' => '✓ terminé',
    'Cada disciplina es un campeonato de la cuenta con sus propias reglas, fixture, llaves o pruebas. Aquí se define su fecha, horario y lugar (para el programa y para avisar cruces de horario), si es solo de varones o damas, cuánto vale en la tabla (factor) y el cupo por delegación.' => 'Chaque discipline est un championnat du compte avec ses propres règles, calendrier, tableaux ou épreuves. Ici on définit sa date, son horaire et son lieu (pour le programme et pour avertir des conflits d\'horaire), si elle est réservée aux hommes ou aux dames, combien elle vaut au classement (coefficient) et le quota par délégation.',
