    'Solo si el resultado no sale del campeonato (por ejemplo, una disciplina que se jugó fuera del sistema). Manda sobre los resultados. Déjelo vacío para usar los del campeonato.' => 'Seulement si le résultat ne vient pas du championnat (par exemple, une discipline jouée hors du système). Il prime sur les résultats. Laissez vide pour utiliser ceux du championnat.',
